source('highres_VisiumHD/analysis/hd_mp10_treg_endo_precommunication_v1/code/common.R');a<-readRDS(file.path(root,'models/fine_reference.rds'));f<-rd('reference_model_features.tsv');genes<-c('EPCAM','KRT7','KRT19','UPK2','KRT5','KRT14','KRT6A','KRT6B','KRT17','COL17A1','FOXP3','IL2RA','CTLA4','IKZF2','LRRC32','TIGIT','PECAM1','VWF','CDH5','EMCN');epi<-a$metadata$label=='Epithelial';rr<-lapply(genes,function(g){present<-g%in%rownames(a$counts);data.frame(gene=g,in_model_gene_space=present,SingleR_DE_selected=if(g%in%f$gene)f$selected_singleR[match(g,f$gene)]else FALSE,Epi_reference_n=sum(epi),Epi_reference_positive=if(present)sum(a$counts[g,epi]>0)else NA,Epi_reference_UMI=if(present)sum(a$counts[g,epi])else NA)});put(do.call(rbind,rr),'reference_target_marker_coverage.tsv');cat('REFERENCE_MARKER_AUDIT_COMPLETE\n')
